#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Complex {
    real: i32,
    imag: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> (Vec<Complex>) {
    // The fixed machine epsilon as given in problem statement:
    const EPSILON: i32 = 2;

    // Calculate the threshold
    let threshold = tol * EPSILON;

    // Check if all imaginary parts are close to zero under the given definition
    let all_imag_close = arr.iter().all(|c| c.imag.abs() <= threshold);

    if all_imag_close {
        // If all imaginary parts are close to zero,
        // produce an output array with imaginary part exactly zero
        // but with real part unchanged.
        // This also satisfies: if input is already real (imag == 0),
        // output equals input.
        let result = arr
            .into_iter()
            .map(|c| Complex {
                real: c.real,
                imag: 0,
            })
            .collect();
        (result)
    } else {
        // Otherwise return input unchanged
        (arr)
    }
}